type Scope struct { parent *Scope; syms map[string]Symbol }
func NewScope(parent *Scope) *Scope { return &Scope{parent, map[string]Symbol{}} }
func (s *Scope) Define(name string, sym Symbol) bool {      // dup -> false
    if _, dup := s.syms[name]; dup { return false }
    s.syms[name] = sym; return true
}
func (s *Scope) Lookup(name string) (Symbol, bool) {        // inner -> outer
    for sc := s; sc != nil; sc = sc.parent {
        if sym, ok := sc.syms[name]; ok { return sym, true }
    }
    return Symbol{}, false
}

